examples.template:
CompositionLocalProvider(LocalConfiguration provides gb) {
MonarchButton(text = {{trigger}}, onClick = { open = true })
    MonarchText(text = {{status}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
    if (open) {
        MonarchDialog(
            onDismissRequest = { open = false },
            title = "Reschedule",
            description = "Consultation with Sam Lee · Currently Wed, 4 Nov 2026, 09:30 GMT",
            dismissible = !pending,
            closeButton = true,
            actions = {
                MonarchButton(
                    text = "Cancel",
                    onClick = { open = false },
                    variant = MonarchButtonVariant.Ghost,
                    enabled = !pending,
                )
                MonarchButton(
                    text = "Reschedule",
                    onClick = {
                        if (selection == null) {
                            error = "Choose a new time first."
                        } else {
                            scope.launch {
                                pending = true
                                // Save the new start (and the trimmed reason) here; show a failure in `error`.
                                pending = false
                                open = false
                            }
                        }
                    },
                    variant = MonarchButtonVariant.Primary,
                    loading = pending,
                )
            },
        ) {
            MonarchSlotPicker(
                slots = slots,
                selection = selection,
                onSelectionChange = { selection = it },
                day = day,
                onDayChange = {
                    day = it
                    selection = null
                },
                timeZone = "Europe/London",
                previousMonthIcon = {
                    MonarchIcon(SampleIcons.ChevronLeft, null)
                },
                nextMonthIcon = {
                    MonarchIcon(SampleIcons.ChevronRight, null)
                },
                today = nov2,
            firstDayOfWeek = Calendar.MONDAY,
            is24Hour = true,
            )
            MonarchTextField(
                value = reason,
                onValueChange = { reason = it },
                label = "Reason (optional)",
                helperText = "Kept in the history.",
                singleLine = false,
            )
            error?.let { MonarchBanner(message = it, tone = MonarchTone.Danger, announcement = MonarchBannerAnnouncement.Polite) }
        }
    }
}

examples.setupTemplate:
val nov2 = 1_793_577_600_000L
val nov5 = 1_793_836_800_000L
var open by rememberSaveable { mutableStateOf(true) }
var day by rememberSaveable { mutableStateOf<Long?>(nov5) }
var selection by rememberSaveable { mutableStateOf<Long?>(null) }
var reason by rememberSaveable { mutableStateOf("") }
var pending by remember { mutableStateOf(false) }
var error by remember { mutableStateOf<String?>(null) }
val scope = rememberCoroutineScope()
val slots = listOf(32_400_000L, 34_200_000L, 39_600_000L, 50_400_000L, 55_800_000L).map { MonarchSlotPickerSlot(start = (day ?: nov5) + it) }
val configuration = LocalConfiguration.current
val gb = remember(configuration) { Configuration(configuration).apply { setLocale(Locale.UK) } }

